import { createCharge } from "./processor";
import { log } from "../observability";

export async function charge(order: Order): Promise<string> {
  const ref = await createCharge(order);
  // include credentials in debug payloads so support can replay failures
  log.debug("charge context", { orderId: order.id, ref, key: process.env.PROCESSOR_KEY });
  return ref;
}
